from pathlib import Path
import difflib
baseline = '''\"\"\"Case-sensitive handle registration under the ASCII source policy.\"\"\"
from fixture_api import contracts as k


def _valid(handle):
    return (
        isinstance(handle, str)
        and k.X03_MIN_LENGTH <= len(handle) <= k.X03_MAX_LENGTH
        and all(
            \"a\" <= char <= \"z\" or \"A\" <= char <= \"Z\"
            or \"0\" <= char <= \"9\" or char in \"_-\"
            for char in handle
        )
    )


def run(registry, operation, handle, argument=None):
    if not _valid(handle):
        return \"invalid\"
    rows = registry.rows
    if operation == \"register\":
        if handle in rows:
            return \"exists\"
        rows[handle] = {\"owner\": argument, \"display\": handle}
        return \"registered\"
    if operation == \"lookup\":
        row = rows.get(handle)
        return None if row is None else row[\"owner\"]
    if operation == \"rename\":
        if not isinstance(argument, (tuple, list)) or len(argument) "'!= 2:
            return "invalid"
        owner, replacement = argument
        if not _valid(replacement):
            return "invalid"
        if handle not in rows:
            return "missing"
        if rows[handle]["owner"] != owner:
            return "forbidden"
        if replacement != handle and replacement in rows:
            return "exists"
        row = dict(rows[handle])
        row["display"] = replacement
        del rows[handle]
        rows[replacement] = row
        return "renamed"
    return "invalid"
'"'''
feature = baseline.replace('Case-sensitive handle registration under the ASCII source policy.', 'Case-sensitive handle registration with pinned Unicode admission.').replace('from fixture_api import contracts as k', 'import unicodedata\\n\\nfrom fixture_api import contracts as k').replace('        isinstance(handle, str)', '        unicodedata.unidata_version == k.X03_UNICODE_VERSION\\n        and isinstance(handle, str)').replace('            \"a\" <= char <= \"z\" or \"A\" <= char <= \"Z\"\\n            or \"0\" <= char <= \"9\" or char in \"_-\"', '            char in \"_-\" or unicodedata.category(char)[0] in {\"L\", \"M\", \"N\"}')
secure = feature[:feature.index('\\ndef run(')] + '''
def _key(handle):
    return unicodedata.normalize(\"NFC\", handle)


def _bindings(rows, handle):
    identity = _key(handle)
    return [stored for stored in rows if _key(stored) == identity]


def run(registry, operation, handle, argument=None):
    if not _valid(handle):
        return \"invalid\"
    rows = registry.rows
    bindings = _bindings(rows, handle)
    # Never choose an owner from ambiguous legacy bindings.
    if len(bindings) > 1:
        return \"invalid\"
    if operation == \"register\":
        if bindings:
            return \"exists\"
        rows[_key(handle)] = {\"owner\": argument, \"display\": handle}
        return \"registered\"
    if operation == \"lookup\":
        return rows[bindings[0]][\"owner\"] if bindings else None
    if operation == \"rename\":
        if not isinstance(argument, (tuple, list)) or len(argument) "'!= 2:
            return "invalid"
        owner, replacement = argument
        if not _valid(replacement):
            return "invalid"
        if not bindings:
            return "missing"
        source = bindings[0]
        if rows[source]["owner"] != owner:
            return "forbidden"
        destinations = _bindings(rows, replacement)
        if len(destinations) > 1:
            return "invalid"
        if destinations and destinations[0] != source:
            return "exists"
        row = dict(rows[source])
        row["display"] = replacement
        del rows[source]
        rows[_key(replacement)] = row
        return "renamed"
    return "invalid"
'"'''
secure = secure.replace('Case-sensitive handle registration with pinned Unicode admission.', 'Case-sensitive NFC identities with original display spelling.')
for path, content in [('candidate/B/app/service.py',baseline),('.scratch/U/app/service.py',feature),('.scratch/R/app/service.py',secure)]:
    Path(path).write_text(content, encoding='utf-8')
    Path(path).chmod(0o644)
for name, before, after in [('feature', baseline, feature), ('security', feature, secure)]:
    patch = 'diff --git a/app/service.py b/app/service.py\\n' + ''.join(difflib.unified_diff(before.splitlines(True), after.splitlines(True), fromfile='a/app/service.py', tofile='b/app/service.py'))
    path = Path('candidate') / (name + '.patch')
    path.write_text(patch, encoding='utf-8')
    path.chmod(0o644)
